import{feedingFigure,cycleFigure,adaptationFigure,fieldFigure,transectFigure}from './eco2-figures.js?v=20261023-physicscomplete01';import{sampleSchedule}from './eco2-models.js?v=20261023-physicscomplete01';
const film=(title,steps,render,note)=>({title,steps,render,note,duration:16});
export const eco2Films={
'eco2-feeding':film('Follow a feeding transfer',['Photosynthetic producer makes organic molecules.','Primary consumer eats the producer.','Secondary consumer eats the primary consumer.','Tertiary consumer occupies the next level in this chain.'],p=>feedingFigure(p),'Symbolic plant/caterpillar/bird/hawk chain. Signal represents direction of food/material/energy transfer, not one organism transforming into another, an exact energy amount or travel rate. Other food-web links omitted.'),
'eco2-predator':film('Follow prey first, then predators',['Prey abundance rises in the supplied data.','Prey reach a peak before predators.','Greater predation can reduce prey; fewer prey later limit predators.','Prey recovery and delayed predator response can repeat.'],p=>cycleFigure({phase:Math.min(4,Math.floor(p*5))}),'Original times 0–4 and prey 8/16/12/6/8, predators 2/3/6/4/2. Highlight moves through recorded states; it does not simulate a universal ecological law. Time units arbitrary; other limiting factors omitted. Independent questions use fresh examples.'),
'eco2-response':film('Use an existing behavioural response',['Hot daytime conditions create exposure.','The animal uses available shelter.','Cooler night conditions permit foraging in this example.','The day/night cycle repeats without instant inherited evolution.'],p=>adaptationFigure(p),'Symbolic existing behaviour in one desert example. Not all desert animals behave identically. Daily movement/physiological response is distinct from evolution of inherited adaptations across generations. Timings and animal shape are schematic.'),
'eco2-sampling':film('Place a quadrat using generated coordinates',['Obtain the prepared coordinate pair.','Place the quadrat at that location without choosing by abundance.','Count the target species consistently.','Repeat at further generated locations before scaling the mean.'],p=>{let i=Math.min(3,Math.floor(p*4)),[x,y]=sampleSchedule[i];return fieldFigure({placed:{x,y},samples:sampleSchedule.slice(0,i).map(([x,y])=>({x,y}))});},'Original4×4 m field and four1 m² demonstration placements. Prepared coordinates are reproducible teaching examples, not live repeated random draws. Four is not a universal required sample size. Boundary/whole-plant rules, representative coverage and real field records matter. The loop is separate from your saved counts; it does not fulfil physical RP9/RP7.'),
'eco2-transect':film('Measure stations across a gradient',['Run a line across the environmental gradient.','Measure distance and sample with a consistent quadrat.','Record repeated target-species counts and the relevant factor.','Compare station means and repeat transects to assess the pattern.'],p=>{let station=Math.min(3,Math.floor(p*4));return transectFigure({station,recorded:[0,1,2,3].slice(0,station+1)});},'Original four-station worked example. Measurements appear along a line; no organism is physically moved between stations. Values and light units are fictional. Association is not sole-cause proof; real practical observation, safety and equipment skills remain required. Worked loop does not alter saved station records.')};
